CREATE OR REPLACE FUNCTION public.reports_options() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN IF NOT public.reports_can('view_reports') THEN RAISE EXCEPTION 'REPORT_ACCESS_DENIED: Reports are available to authorised administrators only.' USING ERRCODE='42501'; END IF; RETURN jsonb_build_object('agencies',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name) ORDER BY name,id) FROM public.agencies),'[]'::jsonb),'launch_date',(SELECT value->>'launch_date' FROM public.platform_settings WHERE key='launch'),'first_date',(SELECT min((created_at AT TIME ZONE 'Africa/Johannesburg')::date) FROM public.profiles),'first_login',(SELECT min(created_at) FROM public.talent_audit_log WHERE action='login'),'capture_started_at',public.sign_in_capture_started_at(),'as_of',now(),'role',(SELECT role FROM public.reports_access WHERE user_id=auth.uid()),'joined_months',COALESCE((SELECT jsonb_agg(month_key ORDER BY month_key DESC) FROM (SELECT DISTINCT to_char((r->>'registered_at')::timestamptz AT TIME ZONE 'Africa/Johannesburg','YYYY-MM') AS month_key FROM public.reports_people_rows(current_date-36500,current_date,'{"accounts":"all","account_type":"all","talent":"all","source":"all","status":"any","agencies":[],"stage":"all","activity":"all"}',now()) r WHERE r->>'registered_at' IS NOT NULL) m),'[]'::jsonb)); END $$;
REVOKE ALL ON FUNCTION public.reports_options() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.reports_options() TO authenticated;
CREATE OR REPLACE FUNCTION public.reports_sign_in_summary(_from date,_to date,_filters jsonb,_prior_from date DEFAULT NULL,_prior_to date DEFAULT NULL,_as_of timestamptz DEFAULT now()) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE result jsonb; BEGIN
IF NOT public.reports_can('view_reports') THEN RAISE EXCEPTION 'REPORT_ACCESS_DENIED: Your Reports role does not allow this action.' USING ERRCODE='42501'; END IF;
WITH people AS MATERIALIZED(SELECT 'current'::text AS period,r FROM public.reports_people_rows(_from,_to,_filters,_as_of) r WHERE (r->>'registered')::boolean OR r->>'account_type'='trusted_contact' UNION ALL SELECT 'prior',r FROM public.reports_people_rows(COALESCE(_prior_from,_from),COALESCE(_prior_to,_to),_filters,_as_of) r WHERE (r->>'registered')::boolean OR r->>'account_type'='trusted_contact'), types AS(SELECT unnest(ARRAY['agency_staff','talent','trusted_contact']) AS typ), stats AS(SELECT t.typ,pr.period,count(*) FILTER(WHERE p.r IS NOT NULL) AS total,count(*) FILTER(WHERE (p.r->>'sign_ins')::numeric>0) AS active,count(*) FILTER(WHERE (p.r->>'active_days')::numeric>=2) AS returning,COALESCE(sum((p.r->>'sign_ins')::numeric),0) AS sign_ins,COALESCE(round(avg((p.r->>'active_days')::numeric) FILTER(WHERE (p.r->>'sign_ins')::numeric>0),2),0) AS average_days,count(*) FILTER(WHERE (p.r->>'dormant')::boolean) AS dormant FROM types t CROSS JOIN (VALUES('current'),('prior')) pr(period) LEFT JOIN people p ON p.period=pr.period AND p.r->>'account_type'=t.typ GROUP BY t.typ,pr.period)
SELECT jsonb_build_object('groups',(SELECT jsonb_agg(jsonb_build_object('type',t.typ,'current',(SELECT to_jsonb(s)-'typ'-'period' FROM stats s WHERE s.typ=t.typ AND s.period='current'),'prior',(SELECT to_jsonb(s)-'typ'-'period' FROM stats s WHERE s.typ=t.typ AND s.period='prior'),'tracking_since',(SELECT min(r->>'first_sign_in') FROM people WHERE period='current' AND r->>'account_type'=t.typ)) ORDER BY t.typ) FROM types t),'unconfirmed_talent',0,'missing_registration_dates',(SELECT count(*) FROM people WHERE period='current' AND (r->>'registered')::boolean AND r->>'registered_at' IS NULL),'unresolved_logins',(SELECT count(*) FROM public.talent_audit_log e WHERE e.action='login' AND e.created_at>=_from::timestamp AT TIME ZONE 'Africa/Johannesburg' AND e.created_at<LEAST((_to+1)::timestamp AT TIME ZONE 'Africa/Johannesburg',_as_of,now()) AND NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=e.actor_id)),'capture_started_at',public.sign_in_capture_started_at(),'as_of',LEAST(_as_of,now()),'prior',jsonb_build_object('from',COALESCE(_prior_from,_from),'to',COALESCE(_prior_to,_to)),'comparison_enabled',_prior_from IS NOT NULL) INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.reports_sign_in_summary(date,date,jsonb,date,date,timestamptz) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.reports_sign_in_summary(date,date,jsonb,date,date,timestamptz) TO authenticated;
